module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding for the FSM
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the three received bytes
    logic [7:0] byte1, byte2, byte3;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            byte1     <= 8'b0;
            byte2     <= 8'b0;
            byte3     <= 8'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-asserted

            case (state)
                IDLE: begin
                    if (in[3]) begin
                        // Found byte 1: MSB is 1, discard rest of bits? 
                        // Specification: "discard bytes until we see one with in[3]=1. We then assume that this is byte 1 of a message"
                        // We store the whole byte as the first byte of the message.
                        byte1 <= in;
                        next_state <= BYTE1;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Wait for second byte
                    next_state <= BYTE2;
                end

                BYTE2: begin
                    // Wait for third byte
                    next_state <= BYTE3;
                end

                BYTE3: begin
                    // Received the third byte, construct the 24-bit message
                    // out_bytes[23:16] = first byte, out_bytes[15:8] = second byte, out_bytes[7:0] = third byte
                    out_bytes <= {byte1, byte2, byte3};
                    done      <= 1'b1; // signal done in the cycle immediately after third byte received
                    next_state <= IDLE; // reset for next message
                end
            endcase
        end
    end

    // Output valid whenever done is asserted (as per specification)
    // The out_bytes register is updated in the BYTE3 state when done goes high.

endmodule

