    // 0011: d -> 0
    // 0100: 0 -> 0
    // 0101: d -> 0
    // 0110: 1 -> 1
    // 0111: d -> 0
    // 1000: 1 -> 1
    // 1001: 1 -> 1
    // 1010: d -> 0
    // 1011: d -> 0
    // 1100: 1 -> 1
    // 1101: 1 -> 1
