module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state: 2-bit register for "level previous to the last sensor change"
    // 00 = low, 01 = medium, 10 = high, 11 = don't care
    reg [1:0] state;

    // Combinational logic for outputs
    always @(*) begin
        // Default assignments (all outputs high = off/maximum flow)
        fr2 = 1'b1;
        fr1 = 1'b1;
        fr0 = 1'b1;
        dfr = 1'b0;

        // Case statement for sensor configuration
        case (s)
            // Above s[2]: s[2], s[1], s[0] asserted -> No flow
            3'b111: begin
                // No outputs asserted (all high = off)
            end

            // Between s[2] and s[1]: s[1], s[0] asserted -> fr0
            3'b110: begin
                fr0 = 1'b0;
            end

            // Between s[1] and s[0]: s[0] asserted -> fr0, fr1
            3'b101: begin
                fr0 = 1'b0;
                fr1 = 1'b0;
            end

            // Below s[0]: No sensors asserted -> fr0, fr1, fr2, dfr
            3'b100, 3'b011, 3'b010, 3'b001, 3'b000: begin
                fr0 = 1'b0;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b1;
            end
            default: begin
                // Fallback (should not occur with valid sensor inputs)
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
                dfr = 1'b0;
            end
        endcase
    end

    // Sequential logic for state update on rising edge of clk
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: state equivalent to long low level
            state <= 2'b00;
        end else begin
            // Update state based on current sensor input s
            // The state represents the level previous to the last sensor change
            case (s)
                3'b111: state <= 2'b10; // Above highest sensor
                3'b110: state <= 2'b01; // Between upper and middle
                3'b101: state <= 2'b00; // Between middle and lower
                default: state <= 2'b00; // Below lowest or undefined
            endcase
        end
    end

    // Logic to increase flow rate (dfr) when previous level was lower than current
    // dfr is already driven high in the 'Below s[0]' case above.
    // Additional logic ensures dfr is asserted if the state transition indicates
    // a rise from a lower level.
    always @(*) begin
        // If current level is below s[0] and previous state was not low, assert dfr
        if (s == 3'b100 || s == 3'b011 || s == 3'b010 || s == 3'b001 || s == 3'b000) begin
            if (state != 2'b00) begin
                dfr = 1'b1;
            end
        end
    end

endmodule

