    // and to generate the output based on the observed pattern.
    reg  [1:0] state; // 2-bit state machine: 00=idle, 01=first_half, 10=second_half, 11=both_high

    // Declare z as a reg so it can be driven inside the always block
    reg z;

    always @(*) begin
        // The output z is determined by the current input combination
        // and the timing pattern observed in the waveform.
        //
        // Pattern analysis:
        // - (0,0) -> z = 1 (always, except during specific transitions if any)
        // - (1,0) -> z = 0
        // - (0,1) -> z = 0
        // - (1,1) -> z = 1
        //
        // This implements a simple logic function:
        // z = 1 when (x==0 & y==0) or (x==1 & y==1)
        // z = 0 when (x==1 & y==0) or (x==0 & y==1)
        //
        // Equivalent to: z = (x & y) | (~x & ~y)
        // Which is the XNOR (equivalence) function.

        // Fixed: assign to z directly in continuous assignment style within always @*
        // Since z is declared as output reg implicitly in some styles, but here it is
        // a wire (output port without reg declaration). To drive it inside always @*,
