module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Fall counter
    logic [4:0] fall_count;

    // Outputs (Moore machine)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_count <= 0;
        end else begin
            state <= next_state;
            // Update fall counter
            if (state == FALLING && next_state != FALLING) begin
                // Transitioning out of fall, reset counter
                fall_count <= 0;
            end else if (state == FALLING) begin
                fall_count <= fall_count + 1;
            end
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall when ground disappears
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction
                    if (bump_left && bump_right) begin
                        // Bumped on both sides - switch to opposite
                        next_state = WALK_RIGHT;
                    end else if (bump_left) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                    end
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    if (bump_left && bump_right) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                    end
                end
            end

            FALLING: begin
                if (ground) begin
                    // Hit the ground
                    if (fall_count > 20) begin
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in same direction
                        next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
                    end
                    fall_count <= 0; // reset counter
                end
                // While falling, ignore bumps and dig
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side, start falling
                    next_state = FALLING;
                    fall_count <= 0;
                end else begin
                    // Still on ground
                    if (!dig) begin
                        // Stop digging, resume walking
                        next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
                    end
                    // While digging on ground, ignore bumps
                end
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
                // All outputs 0 already
            end
        endcase
    end

endmodule

