module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // FSM state encoding
    parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;
    reg [1:0] state, next_state;

    // Outputs
    reg f_reg, g_reg;
    assign f = f_reg;
    assign g = g_reg;

    // State register (synchronous reset, active low)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= A;
            f_reg <= 1'b0;
            g_reg <= 1'b0;
        end else begin
            state <= next_state;
            f_reg <= next_f;
            g_reg <= next_g;
        end
    end

    // Next-state and output logic (combinational)
    always @(*) begin
        next_state = state;
        next_f     = 1'b0;
        next_g     = 1'b0;

        case (state)
            A: begin
                // As long as reset is de-asserted, after next clock edge f=1 for one cycle
                // (handled by state transition on first non-reset clock)
                next_state = B;
            end
            B: begin
                // f is set to 1 for one clock cycle (already captured in f_reg from previous cycle)
                // Monitor x input
                if (x) begin
                    next_state = C;
                end else begin
                    next_state = B;
                end
            end
            C: begin
                // Monitor second clock cycle of x
                if (x) begin
                    next_state = D;
                end else begin
                    next_state = B; // reset x-monitoring if x goes low
                end
            end
            D: begin
                // x sequence 1,0,1 detected; g should be set to 1 on following clock cycle
                next_state = D; // stay in D, g will be asserted next cycle
            end
        endcase

        // g logic
        // While in D (or after g asserted), monitor y
        // If y=1 within at most two clock cycles, maintain g=1 permanently
        // If y does not become 1 within two clock cycles, set g=0 permanently
        // We implement a two-cycle y-watch using states D and E
        case (state)
            D: begin
                // First cycle of y-monitoring in state D
                if (y) begin
                    next_g = 1'b1; // y became 1 within one cycle, maintain g
                    next_state = D; // stay in D to maintain g permanently
                end else begin
                    // y not 1 yet, transition to E to watch the second cycle
                    next_state = E;
                end
            end
            E: begin
                // Second cycle of y-monitoring
                if (y) begin
                    next_g = 1'b1; // y became 1 within two cycles, maintain g
                    next_state = D; // return to D to maintain g permanently
                end else begin
                    // y not 1 within two cycles -> g=0 permanently
                    next_g = 1'b0;
                    next_state = A; // reset to A, g will stay 0 until reset
                end
            end
            default: begin
                next_state = A;
            end
        endcase
    end

    // f pulse logic: f should be 1 for one clock cycle after reset de-assertion
    // We achieve this by setting f_reg high when transitioning from A to B
    always @(posedge clk) begin
        if (!resetn) begin
            f_reg <= 1'b0;
        end else if (state == A && next_state == B) begin
            f_reg <= 1'b1;
        end else begin
            f_reg <= 1'b0;
        end
    end

endmodule

