module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD digits (ones, tens, hundreds, thousands)
);

    // Internal register file for the 4 BCD digits
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // Wire for the next-state increment logic
    // We increment the ones digit every clock cycle (mod-10 counter)
    // and propagate carry to higher digits.

    always @(posedge clk) begin
        if (reset) begin
            ones   <= 4'd0;
            tens   <= 4'd0;
            hundreds <= 4'd0;
            thousands <= 4'd0;
        end else begin
            // --- Ones digit ---
            // Increment ones; if it reaches 9 (4'd9), wrap to 0 and carry to tens.
            if (ones == 4'd9) begin
                ones   <= 4'd0;
                // Carry into tens
                if (tens == 4'd9) begin
                    tens   <= 4'd0;
                    // Carry into hundreds
                    if (hundreds == 4'd9) begin
                        hundreds <= 4'd0;
                        // Carry into thousands
                        if (thousands == 4'd9) begin
                            thousands <= 4'd0;
                        end else begin
                            thousands <= thousands + 1'b1;
                        end
                    end else begin
                        hundreds <= hundreds + 1'b1;
                    end
                end else begin
                    tens <= tens + 1'b1;
                end
            end else begin
                ones <= ones + 1'b1;
            end
        end
    end

    // --- Output assignments ---
    // q is the concatenation of the four BCD digits: thousands hundreds tens ones
    assign q = {thousands, hundreds, tens, ones};

    // ena signals:
    // ena[0] -> tens enable (carry from ones)
    // ena[1] -> hundreds enable (carry from tens)
    // ena[2] -> thousands enable (carry from hundreds)
    // We generate these based on the internal carry conditions.
    // Since the counter increments every cycle, ena reflects when the
    // corresponding digit *would* be incremented in the next cycle
    // (or is currently being incremented). We output the enable based
    // on the current state conditions.
    assign ena = {
        // ena[0]: tens enable — asserted when ones is at 9 (next cycle carry)
        (ones == 4'd9),
        // ena[1]: hundreds enable — asserted when ones is at 9 AND tens is at 9
        (ones == 4'd9 && tens == 4'd9),
        // ena[2]: thousands enable — asserted when ones,tens,hundreds are all at 9
        (ones == 4'd9 && tens == 4'd9 && hundreds == 4'd9)
    };

endmodule
